## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/ccmLogic.ts`

```typescript
/**
 * Cerebral Cavernous Malformation (CCM) Clinical Logic Engine
 *
 * Based on:
 * - Angioma Alliance / CNS 2025 Updated Consensus Recommendations for CCM Management
 * - Akers A et al. Synopsis of Guidelines for CCM (Neurosurgery 2017)
 * - AHA/ASA 2021 Stroke Prevention Guidelines
 * - Al-Shahi Salman R et al. Lancet Neurol 2012 (natural history)
 * - Horne MA et al. Lancet Neurol 2016 (meta-analysis)
 * - Josephson CB et al. Neurology 2011 (seizure risk)
 *
 * PMIDs: 28282516, 34025742, 22265208, 26708940, 21536040
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type CCMType = "sporadic" | "familial";

export type CCMLocation =
  | "noneloquent_cortical" // Easily accessible, non-eloquent
  | "eloquent_cortical" // Motor, language, sensory cortex
  | "deep_subcortical" // Basal ganglia, thalamus
  | "brainstem"
  | "spinal_dorsal_dorsolateral"
  | "spinal_ventral_embedded";

export type HemorrhageStatus =
  | "no_hemorrhage"
  | "single_hemorrhage"
  | "recurrent_hemorrhage"; // ≥2 symptomatic bleeds

export type SeizureStatus =
  | "no_seizure"
  | "controlled_seizure" // Controlled on ASM
  | "refractory_seizure"; // Medically refractory epilepsy

export type PrimaryRecommendation =
  | "observation"
  | "surgical_resection"
  | "radiosurgery_srs"
  | "laser_thermal_ablation"
  | "genetic_testing_first"
  | "urgent_surgery"
  | "antiseizure_medication";

export interface CCMInput {
  // CCM characteristics
  ccmType: CCMType;
  location: CCMLocation;
  cmSizeCm: number;
  associatedDVA: boolean; // Developmental venous anomaly
  multiplelesions: boolean;

  // Clinical presentation
  symptomatic: boolean;
  hemorrhageStatus: HemorrhageStatus;
  seizureStatus: SeizureStatus;
  neurologicDeficit: boolean;
  headacheOnly: boolean;
  incidentalFinding: boolean;

  // Genetic factors
  familyHistory: boolean;
  knownCCMGeneVariant?: "ccm1" | "ccm2" | "ccm3" | "unknown";
  priorCranialIrradiation: boolean;

  // Patient factors
  ageYears: number;
  pediatricPatient: boolean; // <18 years
  pregnancyStatus: boolean;
  surgicalRisk: "low" | "moderate" | "high";

  // Prior treatments
  priorSurgery: boolean;
  priorSRS: boolean;
  priorASM: boolean; // Antiseizure medication
  asmResponse?: "controlled" | "refractory";

  // Spinal-specific
  spinalCM: boolean;
  acuteNeurologicImpairment: boolean;
  progressiveNeurologicDeterioration: boolean;
}

export interface CCMRecommendation {
  primaryRecommendation: PrimaryRecommendation;
  recommendationTitle: string;
  rationale: string;
  evidenceClass: "I" | "IIa" | "IIb" | "III";
  evidenceLevel: "A" | "B" | "C" | "EO" | "LD" | "NR";
  guidelineSource: string;

  // Management details
  surgicalConsiderations: string[];
  radiosurgeryConsiderations: string[];
  medicalManagement: string[];
  geneticCounseling: string[];

  // Monitoring
  monitoringPlan: string[];

  // Warnings and flags
  urgentFlags: string[];
  warnings: string[];

  // Next steps
  nextSteps: string[];

  // References
  references: Array<{ citation: string; pmid?: string }>;
}

// ─── Core Logic ──────────────────────────────────────────────────────────────

export function assessCCM(input: CCMInput): CCMRecommendation {
  const urgentFlags: string[] = [];
  const warnings: string[] = [];
  const surgicalConsiderations: string[] = [];
  const radiosurgeryConsiderations: string[] = [];
  const medicalManagement: string[] = [];
  const geneticCounseling: string[] = [];
  const monitoringPlan: string[] = [];

  // ── Urgent flags ──────────────────────────────────────────────────────────
  if (input.spinalCM && input.acuteNeurologicImpairment) {
    urgentFlags.push(
      "Acute spinal CM hemorrhage with rapid neurological deterioration: Urgent surgical resection may be considered (subject to patient comorbidities and preferences)."
    );
  }
  if (
    input.neurologicDeficit &&
    input.hemorrhageStatus === "recurrent_hemorrhage"
  ) {
    urgentFlags.push(
      "Recurrent hemorrhage with neurologic deficit: Surgical evaluation urgently recommended."
    );
  }
  if (input.knownCCMGeneVariant === "ccm3") {
    warnings.push(
      "CCM3 mutation: Associated with higher hemorrhage rate and more aggressive clinical course. Closer surveillance warranted."
    );
  }

  // ── Genetic counseling ────────────────────────────────────────────────────
  if (input.ccmType === "familial" || input.familyHistory) {
    geneticCounseling.push(
      "Familial CCM: Genetic testing for CCM1, CCM2, CCM3 pathogenic variants is recommended (CNS 2025)."
    );
    geneticCounseling.push(
      "Autosomal dominant inheritance: Counsel on 50% risk to first-degree relatives."
    );
    geneticCounseling.push(
      "At-risk family members: Genetic testing can guide healthcare decisions. Genetic specialist consultation recommended before screening asymptomatic individuals."
    );
    geneticCounseling.push(
      "Psychological consequences of diagnostic testing: Counsel asymptomatic at-risk individuals before testing."
    );
    if (input.pregnancyStatus) {
      geneticCounseling.push(
        "Pregnancy with familial/multifocal CCM: Consider genetic counseling before pregnancy."
      );
    }
  }

  // ── Pregnancy considerations ──────────────────────────────────────────────
  if (input.pregnancyStatus) {
    warnings.push(
      "Pregnancy: Risk of neurological symptoms from CCM is likely not different than non-pregnant state (CNS 2025, Class IIb, Level C)."
    );
    warnings.push(
      "Surgery for asymptomatic CM with goal of safer pregnancy is NOT recommended (CNS 2025, Class III)."
    );
    if (input.seizureStatus !== "no_seizure") {
      medicalManagement.push(
        "Seizure disorder on ASM + pregnancy: Folate supplementation should be considered (CNS 2025)."
      );
    }
  }

  // ── Headache only — no hemorrhage, no seizure ─────────────────────────────
  if (input.headacheOnly && !input.symptomatic) {
    medicalManagement.push(
      "CCM with headache and no secondary cause: Classify and treat according to standard headache practice (CNS 2025)."
    );
    medicalManagement.push(
      "Non-aspirin NSAIDs can be used with caution for nonhemorrhagic CCM lesions."
    );
  }

  // ── Genetic testing first — familial criteria ─────────────────────────────
  if (
    (input.ccmType === "familial" || input.familyHistory) &&
    !input.knownCCMGeneVariant
  ) {
    return {
      primaryRecommendation: "genetic_testing_first",
      recommendationTitle: "Genetic Testing — Familial CCM Criteria Met",
      rationale:
        "Clinical criteria for familial CCM are met. Genetic testing for CCM1, CCM2, CCM3 pathogenic variants is recommended. Pathogenic variant identification guides counseling of at-risk family members and management decisions.",
      evidenceClass: "IIa",
      evidenceLevel: "C",
      guidelineSource:
        "CNS 2025 CCM Consensus; Akers A et al. Neurosurgery 2017 (PMID 28282516)",
      surgicalConsiderations,
      radiosurgeryConsiderations,
      medicalManagement,
      geneticCounseling,
      monitoringPlan: [
        "MRI brain with SWI (susceptibility-weighted imaging) at diagnosis",
        "Annual MRI surveillance for known CCM",
        "Genetic specialist consultation",
      ],
      urgentFlags,
      warnings,
      nextSteps: [
        "Medical genetics consultation for CCM1/2/3 testing",
        "MRI brain with SWI for complete lesion inventory",
        "Counsel at-risk family members",
        "Neurosurgery consultation for symptomatic lesions",
      ],
      references: getCCMReferences(),
    };
  }

  // ── Asymptomatic CCM — observation vs surgery ─────────────────────────────
  if (input.incidentalFinding || (!input.symptomatic && !input.seizureStatus)) {
    // Asymptomatic in eloquent/deep/brainstem or multiple — no surgery
    if (
      input.location === "eloquent_cortical" ||
      input.location === "deep_subcortical" ||
      input.location === "brainstem" ||
      input.multiplelesions
    ) {
      return {
        primaryRecommendation: "observation",
        recommendationTitle:
          "Observation — Asymptomatic CCM in Eloquent/Deep Location",
        rationale:
          "Surgical resection is NOT recommended for asymptomatic CM in eloquent, deep, or brainstem areas, or for multiple asymptomatic CMs (CNS 2025, Class III). Annual hemorrhage risk for unruptured CCM is approximately 0.5–1% per year.",
        evidenceClass: "III",
        evidenceLevel: "B",
        guidelineSource:
          "CNS 2025 CCM Consensus; Al-Shahi Salman R et al. Lancet Neurol 2012 (PMID 22265208)",
        surgicalConsiderations: [
          "Surgery NOT recommended for asymptomatic eloquent/deep/brainstem CCM.",
          "Surgery NOT recommended for multiple asymptomatic CCMs.",
          "Surgery NOT recommended with goal of safer pregnancy.",
        ],
        radiosurgeryConsiderations: [
          "Radiosurgery NOT recommended for asymptomatic CCMs (CNS 2025, Class III).",
        ],
        medicalManagement: [
          ...medicalManagement,
          "Non-aspirin NSAIDs can be used with caution.",
          "Avoid anticoagulation unless strong indication (DVT/PE) — discuss risk/benefit.",
        ],
        geneticCounseling,
        monitoringPlan: [
          "MRI brain with SWI annually × 3 years, then every 2 years if stable",
          "Clinical assessment for new symptoms at each visit",
          "Patient education: Report new headaches, seizures, focal deficits immediately",
        ],
        urgentFlags,
        warnings: [
          ...warnings,
          "Annual hemorrhage risk: ~0.5–1% for unruptured CCM; higher for brainstem location (~2–3%/year).",
          input.knownCCMGeneVariant === "ccm3"
            ? "CCM3 mutation: Higher hemorrhage rate — closer surveillance recommended."
            : "",
        ].filter(Boolean),
        nextSteps: [
          "Annual MRI with SWI",
          "Patient education on warning symptoms",
          "Neurosurgery follow-up annually",
          "Genetic counseling if familial",
        ],
        references: getCCMReferences(),
      };
    }

    // Asymptomatic in accessible noneloquent area — surgery may be considered
    if (input.location === "noneloquent_cortical") {
      surgicalConsiderations.push(
        "Solitary asymptomatic CM in easily accessible noneloquent area: Surgical resection MAY be considered to prevent future hemorrhage, reduce psychological burden, follow-up costs, and lifestyle/career considerations (CNS 2025, Class IIb)."
      );
      return {
        primaryRecommendation: "observation",
        recommendationTitle:
          "Observation (Surgery May Be Considered) — Accessible Noneloquent CCM",
        rationale:
          "Solitary asymptomatic CM in easily accessible noneloquent area: Observation is the default. Surgery may be considered after shared decision-making, weighing future hemorrhage risk against surgical risk.",
        evidenceClass: "IIb",
        evidenceLevel: "C",
        guidelineSource:
          "CNS 2025 CCM Consensus; Akers A et al. Neurosurgery 2017 (PMID 28282516)",
        surgicalConsiderations,
        radiosurgeryConsiderations: [
          "Radiosurgery not recommended for asymptomatic CCM.",
        ],
        medicalManagement,
        geneticCounseling,
        monitoringPlan: [
          "MRI brain with SWI every 6–12 months",
          "Shared decision-making discussion annually",
        ],
        urgentFlags,
        warnings,
        nextSteps: [
          "Shared decision-making: Discuss observation vs surgery",
          "MRI brain with SWI in 6 months",
          "Neurosurgery consultation for surgical risk assessment",
        ],
        references: getCCMReferences(),
      };
    }
  }

  // ── Refractory seizure — surgery recommended ──────────────────────────────
  if (input.seizureStatus === "refractory_seizure") {
    surgicalConsiderations.push(
      "Medically refractory epilepsy with epileptogenic CM identified: Early surgical resection for seizure control is beneficial (CNS 2025, Class IIa, Level B)."
    );
    surgicalConsiderations.push(
      "Nonhemorrhagic CM (especially familial): Careful review by neurologist and EEG to confirm CM-seizure relationship before resection."
    );
    return {
      primaryRecommendation: "surgical_resection",
      recommendationTitle:
        "Surgical Resection — Medically Refractory Epilepsy",
      rationale:
        "Medically refractory epilepsy with epileptogenic CCM identified: Early surgical resection is beneficial for seizure control (CNS 2025, Class IIa, Level B). EEG and neurologist review required to confirm CM-seizure relationship.",
      evidenceClass: "IIa",
      evidenceLevel: "B",
      guidelineSource:
        "CNS 2025 CCM Consensus; Josephson CB et al. Neurology 2011 (PMID 21536040)",
      surgicalConsiderations,
      radiosurgeryConsiderations: [
        "Laser thermal ablation: May be considered for smaller symptomatic CM causing seizures (CNS 2025).",
      ],
      medicalManagement: [
        ...medicalManagement,
        "First-time seizure from CM without associated hemorrhage: Conservative approach with ASM recommended (CNS 2025).",
      ],
      geneticCounseling,
      monitoringPlan: [
        "MRI brain with SWI postoperatively",
        "EEG monitoring postoperatively",
        "Neurology follow-up for seizure management",
        "Neuropsychological assessment",
      ],
      urgentFlags,
      warnings: [
        ...warnings,
        "Nonhemorrhagic CM: Confirm CM is the epileptogenic focus with EEG before surgery.",
        "Familial CCM: Higher risk of de novo CM genesis — continued surveillance required.",
      ],
      nextSteps: [
        "Epilepsy surgery evaluation (video-EEG monitoring)",
        "Neurosurgery consultation",
        "Neuropsychological testing",
        "Confirm CM-seizure relationship with EEG",
        "Discuss laser thermal ablation as alternative if smaller lesion",
      ],
      references: getCCMReferences(),
    };
  }

  // ── Brainstem CCM — second symptomatic bleed ──────────────────────────────
  if (
    input.location === "brainstem" &&
    input.hemorrhageStatus === "recurrent_hemorrhage"
  ) {
    surgicalConsiderations.push(
      "Brainstem CCM with second symptomatic bleed: Complete surgical resection may be offered (CNS 2025, Class IIa)."
    );
    surgicalConsiderations.push(
      "Brainstem CCM with single disabling bleed: Resection may be considered (CNS 2025, Class IIb)."
    );
    return {
      primaryRecommendation: "surgical_resection",
      recommendationTitle:
        "Surgical Resection — Brainstem CCM with Recurrent Hemorrhage",
      rationale:
        "Brainstem CCM with second symptomatic bleed: Complete surgical resection may be offered (CNS 2025, Class IIa). Annual re-hemorrhage risk after first bleed is approximately 3–5% for brainstem CCM.",
      evidenceClass: "IIa",
      evidenceLevel: "C",
      guidelineSource:
        "CNS 2025 CCM Consensus; Horne MA et al. Lancet Neurol 2016 (PMID 26708940)",
      surgicalConsiderations,
      radiosurgeryConsiderations: [
        "Radiosurgery: May be considered for eloquent areas with unacceptably high surgical risk (CNS 2025, Class IIb).",
        "Radiosurgery evidence for brainstem CCM is limited — discuss with multidisciplinary team.",
      ],
      medicalManagement,
      geneticCounseling,
      monitoringPlan: [
        "MRI brain with SWI postoperatively",
        "Annual MRI surveillance if observation chosen",
        "Neurologic assessment at each visit",
      ],
      urgentFlags,
      warnings: [
        ...warnings,
        "Brainstem CCM surgery: High-risk procedure requiring experienced skull base neurosurgeon.",
        "Timing of surgery: Wait 4–6 weeks after acute hemorrhage for clot liquefaction (easier resection).",
      ],
      nextSteps: [
        "Neurosurgery consultation at high-volume skull base center",
        "MRI brain with SWI (thin-cut brainstem protocol)",
        "Multidisciplinary neurovascular team review",
        "Discuss radiosurgery if surgical risk is prohibitive",
      ],
      references: getCCMReferences(),
    };
  }

  // ── Symptomatic accessible CCM — surgery ─────────────────────────────────
  if (
    input.symptomatic &&
    (input.location === "noneloquent_cortical" ||
      input.location === "spinal_dorsal_dorsolateral")
  ) {
    surgicalConsiderations.push(
      "Symptomatic easily accessible CM lesions: Surgery may be considered (CNS 2025, Class IIb)."
    );
    if (input.spinalCM) {
      surgicalConsiderations.push(
        "Dorsal or dorsolateral spinal CCM with exophytic or pial presentation: Surgical resection may be considered (CNS 2025)."
      );
      if (input.acuteNeurologicImpairment) {
        surgicalConsiderations.push(
          "Single acute neurological impairing event: Surgical resection may be considered."
        );
      }
      if (input.progressiveNeurologicDeterioration) {
        surgicalConsiderations.push(
          "Progressive neurological deterioration: Surgical resection may be considered."
        );
      }
    }
    return {
      primaryRecommendation: "surgical_resection",
      recommendationTitle: "Surgical Resection — Symptomatic Accessible CCM",
      rationale:
        "Symptomatic CCM in easily accessible location: Surgery may be considered (CNS 2025, Class IIb). Surgical resection eliminates re-hemorrhage risk and may improve neurologic symptoms.",
      evidenceClass: "IIb",
      evidenceLevel: "C",
      guidelineSource:
        "CNS 2025 CCM Consensus; Akers A et al. Neurosurgery 2017 (PMID 28282516)",
      surgicalConsiderations,
      radiosurgeryConsiderations,
      medicalManagement,
      geneticCounseling,
      monitoringPlan: [
        "MRI brain/spine with SWI postoperatively",
        "Neurologic assessment at 6 weeks, 3 months, then annually",
      ],
      urgentFlags,
      warnings,
      nextSteps: [
        "Neurosurgery consultation",
        "MRI with SWI for surgical planning",
        "Shared decision-making discussion",
      ],
      references: getCCMReferences(),
    };
  }

  // ── Eloquent/deep CCM with prior hemorrhage — radiosurgery option ─────────
  if (
    (input.location === "eloquent_cortical" ||
      input.location === "deep_subcortical") &&
    input.hemorrhageStatus !== "no_hemorrhage" &&
    input.surgicalRisk === "high"
  ) {
    radiosurgeryConsiderations.push(
      "Solitary CM with previous symptomatic hemorrhage in eloquent area with unacceptably high surgical risk: Radiosurgery may be considered (CNS 2025, Class IIb)."
    );
    return {
      primaryRecommendation: "radiosurgery_srs",
      recommendationTitle:
        "Stereotactic Radiosurgery — Eloquent CCM with High Surgical Risk",
      rationale:
        "Solitary CM with previous symptomatic hemorrhage in eloquent area with unacceptably high surgical risk: Radiosurgery may be considered (CNS 2025, Class IIb). Evidence is limited — multidisciplinary review required.",
      evidenceClass: "IIb",
      evidenceLevel: "C",
      guidelineSource:
        "CNS 2025 CCM Consensus; Lunsford LD et al. J Neurosurg 2017",
      surgicalConsiderations: [
        "Surgery not recommended due to high surgical risk in eloquent location.",
      ],
      radiosurgeryConsiderations,
      medicalManagement,
      geneticCounseling,
      monitoringPlan: [
        "MRI brain with SWI at 6 months post-SRS, then annually",
        "Neurologic assessment at each visit",
      ],
      urgentFlags,
      warnings: [
        ...warnings,
        "SRS for CCM: Evidence is limited. Radiosurgery does NOT eliminate re-hemorrhage risk in the first 2 years.",
        "Asymptomatic CCM: Radiosurgery is NOT recommended.",
      ],
      nextSteps: [
        "Radiation oncology consultation for SRS planning",
        "Multidisciplinary neurovascular team review",
        "Discuss observation vs SRS trade-offs",
      ],
      references: getCCMReferences(),
    };
  }

  // ── Default: observation ──────────────────────────────────────────────────
  monitoringPlan.push("MRI brain with SWI every 6–12 months");
  monitoringPlan.push("Clinical assessment for new symptoms");

  return {
    primaryRecommendation: "observation",
    recommendationTitle: "Observation — Active Surveillance",
    rationale:
      "Observation with serial MRI is the default management for most CCMs without high-risk features. Annual hemorrhage risk for unruptured CCM is approximately 0.5–1% per year.",
    evidenceClass: "IIa",
    evidenceLevel: "B",
    guidelineSource:
      "CNS 2025 CCM Consensus; Al-Shahi Salman R et al. Lancet Neurol 2012 (PMID 22265208)",
    surgicalConsiderations,
    radiosurgeryConsiderations,
    medicalManagement: [
      ...medicalManagement,
      "Non-aspirin NSAIDs can be used with caution for nonhemorrhagic CCM.",
      "Anticoagulation: Use only if strong indication — discuss risk/benefit with neurosurgery.",
    ],
    geneticCounseling,
    monitoringPlan,
    urgentFlags,
    warnings,
    nextSteps: [
      "MRI brain with SWI (susceptibility-weighted imaging) for complete lesion inventory",
      "Neurosurgery follow-up annually",
      "Patient education: Report new headaches, seizures, or focal deficits immediately",
      input.ccmType === "familial" ? "Genetic counseling referral" : "",
    ].filter(Boolean),
    references: getCCMReferences(),
  };
}

// ─── Helper Functions ─────────────────────────────────────────────────────────

function getCCMReferences() {
  return [
    {
      citation:
        "Akers A et al. Synopsis of Guidelines for the Clinical Management of Cerebral Cavernous Malformations: Consensus Recommendations Based on Systematic Literature Review by the Angioma Alliance Scientific Advisory Board Clinical Experts Panel. Neurosurgery. 2017;80(5):665-680.",
      pmid: "28282516",
    },
    {
      citation:
        "Al-Shahi Salman R et al. Untreated Clinical Course of Cerebral Cavernous Malformations: A Prospective, Population-Based Cohort Study. Lancet Neurol. 2012;11(3):217-224.",
      pmid: "22265208",
    },
    {
      citation:
        "Horne MA et al. Clinical Course of Untreated Cerebral Cavernous Malformations: A Meta-Analysis of Individual Patient Data. Lancet Neurol. 2016;15(2):166-173.",
      pmid: "26708940",
    },
    {
      citation:
        "Josephson CB et al. Seizure Risk from Cavernous or Arteriovenous Malformations: Prospective Population-Based Study. Neurology. 2011;76(18):1548-1554.",
      pmid: "21536040",
    },
    {
      citation:
        "Kleindorfer DO et al. 2021 Guideline for the Prevention of Stroke in Patients with Stroke and TIA: AHA/ASA Guideline. Stroke. 2021;52(7):e364-e467.",
      pmid: "34025742",
    },
    {
      citation:
        "Lunsford LD et al. Stereotactic Radiosurgery for Cerebral Cavernous Malformations: A Systematic Review and Meta-Analysis. J Neurosurg. 2017;126(4):1088-1099.",
    },
    {
      citation:
        "Dammann P et al. Outcome After Conservative Management or Surgical Treatment for New-Onset Epilepsy in Cerebral Cavernous Malformation. J Neurosurg. 2017;126(4):1303-1311.",
    },
  ];
}

export function getRecommendationColor(rec: PrimaryRecommendation): string {
  switch (rec) {
    case "urgent_surgery":
      return "red";
    case "surgical_resection":
      return "blue";
    case "radiosurgery_srs":
      return "purple";
    case "laser_thermal_ablation":
      return "orange";
    case "antiseizure_medication":
      return "yellow";
    case "genetic_testing_first":
      return "teal";
    case "observation":
      return "green";
    default:
      return "gray";
  }
}

export function getLocationLabel(loc: CCMLocation): string {
  const labels: Record<CCMLocation, string> = {
    noneloquent_cortical: "Noneloquent cortex (easily accessible)",
    eloquent_cortical: "Eloquent cortex (motor, language, sensory)",
    deep_subcortical: "Deep subcortical (basal ganglia, thalamus)",
    brainstem: "Brainstem",
    spinal_dorsal_dorsolateral: "Spinal — dorsal/dorsolateral (exophytic/pial)",
    spinal_ventral_embedded: "Spinal — ventral/embedded (intramedullary)",
  };
  return labels[loc] ?? loc;
}
